public class Main {
    public static void main(String[] args) {
        int a = 0b11001010;
        System.out.println(a & 0b10110110);
        System.out.println(a | 0b10110110);
        System.out.println(a ^ 0b10110110);
        System.out.println(a << 1);
        System.out.println(-8 >> 1);
        System.out.println(-8 >>> 1);
    }
}

public class Main {
    public static void main(String[] args) {
        int[] nums = { 0b00001001, 0b00000101, 0b10001000, 0b00000011 };
        int third = 0;
        int first = 0;
        for (int n : nums) {
            if ((n >> 3 & 1) == 1) {
                third++;
            }
            if ((n >> 0 & 1) == 1) {
                first++;
            }
        }
        System.out.println(third);
        System.out.println(first);
    }
}
